import{_ as e,c as r,o as a,a4 as t}from"./chunks/framework.DzOtv0XR.js";const b=JSON.parse('{"title":"electron","description":"","frontmatter":{},"headers":[],"relativePath":"project/electron.md","filePath":"project/electron.md"}'),o={name:"project/electron.md"},l=t(`<h1 id="electron" tabindex="-1">electron <a class="header-anchor" href="#electron" aria-label="Permalink to &quot;electron&quot;">​</a></h1><p>Electron == CEF + Node.js</p><p>CEF： Chromium 嵌入式框架</p><p><img src="https://pic3.zhimg.com/v2-f85361afb9a037b24b279c9a87d6635e_r.jpg" alt="v2-f85361afb9a037b24b279c9a87d6635e_r.jpg (490×454)"></p><h2 id="cef-chromium-嵌入式框架" tabindex="-1">CEF： Chromium 嵌入式框架 <a class="header-anchor" href="#cef-chromium-嵌入式框架" aria-label="Permalink to &quot;CEF： Chromium 嵌入式框架&quot;">​</a></h2><p>CEF专注于促进第三方应用程序中的嵌入式浏览器用例</p><p>C++ 实现</p><blockquote><p>CEF支持广泛的编程语言和操作系统，可以轻松地集成到新的和现有的应用程序中。它的设计从头到尾兼顾了性能和易用性。基本框架包括通过本机库公开的C和c++编程接口，本机库将主机应用程序与Chromium和Blink实现细节隔离开来。它提供了浏览器和主机应用程序之间的紧密集成，包括对自定义插件、协议、JavaScript对象和JavaScript扩展的支持。主机应用程序可以选择性地控制资源加载、导航、上下文菜单、打印等，同时利用谷歌Chrome Web浏览器中提供的相同性能和HTML5技术。</p></blockquote><p>底层是 Google 公司带头的开源社区</p><p><a href="https://github.com/chromiumembedded/cef" target="_blank" rel="noreferrer">https://github.com/chromiumembedded/cef</a></p><p>组件：</p><ul><li>动态库（各平台）</li><li>支持文件</li><li>资源</li><li>可执行 client</li></ul><p>架构</p><ul><li>CEF使用多个进程。主要的应用程序进程称为“浏览器”进程。将为渲染器、插件、GPU等创建子进程。</li><li>在Windows和Linux上，相同的可执行文件可以用于主进程和子进程。在OS X上，你需要为子进程创建一个单独的可执行文件和应用程序包。</li><li>CEF中的大多数进程都有多个线程。CEF为在这些不同的线程之间提交任务提供了函数和接口。</li><li>一些回调和函数只能在特定进程或特定线程上使用。在第一次开始使用新的回调函数或函数之前，请确保阅读API头中的源代码注释。</li></ul><p><a href="https://blog.scottlogic.com/2023/02/01/webview2-electron-challengers-and-slightly-lighter-desktop-web-applications.html" target="_blank" rel="noreferrer">https://blog.scottlogic.com/2023/02/01/webview2-electron-challengers-and-slightly-lighter-desktop-web-applications.html</a></p><h2 id="进程" tabindex="-1">进程 <a class="header-anchor" href="#进程" aria-label="Permalink to &quot;进程&quot;">​</a></h2><ul><li>2 个进程：主进程和渲染器进程</li><li>web页面运行在渲染进程</li><li>与浏览器区别，页面可访问底层（通过主进程）</li><li>GUI 操作，必须与主进程通讯</li><li>require 时需要引 remote <a href="https://stackoverflow.com/questions/45639628/how-to-fix-browserwindow-is-not-a-constructor-error-when-creating-child-window-i" target="_blank" rel="noreferrer">javascript - How to fix BrowserWindow is not a constructor error when creating child window in Electron renderer process - Stack Overflow</a></li><li>nodeIntegration 5.0 起默认为 false</li></ul><p><a href="https://jlongster.com/secret-of-good-electron-apps" target="_blank" rel="noreferrer">The Secret of Good Electron Apps</a></p><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><p>最好打开开发工具，<code>CTRL-ALT-T</code> 新开页无法使用开发工具？</p><h2 id="窗口管理" tabindex="-1">窗口管理 <a class="header-anchor" href="#窗口管理" aria-label="Permalink to &quot;窗口管理&quot;">​</a></h2><p>不用<code>window.open</code>，<code>a target=_blank</code>开新窗口就可用<code>window.close</code>关掉 进阶，可以用</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { remote } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;electron&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> win </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remote.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getCurrentWindow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">win.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">close</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p><a href="https://codepen.io/cyio/pen/QZPLaV" target="_blank" rel="noreferrer">electron test close window</a><a href="https://electronjs.org/docs/tutorial/application-architecture#%25E9%25A2%2598%25E5%25A4%2596%25E8%25AF%259D%25EF%25BC%259A%25E8%25BF%259B%25E7%25A8%258B%25E9%2597%25B4%25E9%2580%259A%25E8%25AE%25AF" target="_blank" rel="noreferrer">Electron 应用架构 | Electron 进程通讯</a><a href="https://electronjs.org/docs/faq#%25E5%25A6%2582%25E4%25BD%2595%25E5%259C%25A8%25E4%25B8%25A4%25E4%25B8%25AA%25E7%25BD%2591%25E9%25A1%25B5%25E9%2597%25B4%25E5%2585%25B1%25E4%25BA%25AB%25E6%2595%25B0%25E6%258D%25AE%25EF%25BC%259F" target="_blank" rel="noreferrer">Electron 常见问题 (FAQ) | Electron 如何在两个网页间共享数据</a></p><ul><li>推荐使用 preload <a href="https://electronjs.org/docs/tutorial/security#2-do-not-enable-nodejs-integration-for-remote-content" target="_blank" rel="noreferrer">安全性，原生能力和你的责任 | Electron </a><a href="https://changkun.us/archives/2017/03/217/" target="_blank" rel="noreferrer">Electron 深度实践总结 | 欧长坤的博客</a></li></ul><h2 id="ipc-进程通信" tabindex="-1">IPC-进程通信 <a class="header-anchor" href="#ipc-进程通信" aria-label="Permalink to &quot;IPC-进程通信&quot;">​</a></h2><ol><li>主进程与渲染进程</li><li>渲染进程之间 <ul><li>本地存储</li><li>主进程中转（因为两个进程平行，只能通过父级通信）</li></ul></li></ol><p>send 不需要回复。场景：计数、数据更新</p><p>invoke 执行方法（便利），promise 。场景：获取 electron 设置</p><p>postMessage 消息通道，与 Web 中的等价。场景：消息保证、即使监听器还未注册，主进程作为中间人、连接两个渲染进程</p><p>webview document.title/executeJavaScript</p><p>~~remote 模块，模拟本地调用，废弃，推荐 invoke ~~ electron 的 IPC 基于 chromium 的 IPC？</p><p>MessagePort对象可以在渲染器或主进程中创建，并使用ipcRenderer.postMessage和WebContents.postMessage方法来回传递。请注意，通常的IPC方法（如send和invoke）不能用于传输MessagePorts，只有postMessage方法可以传输MessagePorts。</p><p><a href="https://www.electronjs.org/docs/latest/tutorial/message-ports/" target="_blank" rel="noreferrer">https://www.electronjs.org/docs/latest/tutorial/message-ports/</a></p><p><a href="https://zhuanlan.zhihu.com/p/453287153" target="_blank" rel="noreferrer">Electron进程通信 - 知乎</a><a href="https://juejin.cn/post/6988484297485189127" target="_blank" rel="noreferrer">前端不懂进程通信？看完这篇就懂了 - 掘金</a></p><h3 id="ipc-效率与安全" tabindex="-1">IPC 效率与安全 <a class="header-anchor" href="#ipc-效率与安全" aria-label="Permalink to &quot;IPC  效率与安全&quot;">​</a></h3><ul><li>在 Electron 应用中，存在权责问题，即应该在渲染进程还是主进程执行某些操作，例如发起请求或读写文件。</li><li>移植 Electron 应用至 Web 环境时，需要确保渲染进程的安全性和沙箱化。</li><li>在渲染进程中赋予文件系统（fs）能力可能存在安全隐患，因此通过主进程处理字节码，渲染进程通过 IPC 通信可提高安全性。</li><li>Electron 版本升级后，由于引入 preload.js 导致部分功能无法使用，需要社区迁移包临时替代，使得大量功能转移到了 preload.js 中。</li><li>IPC 使用一种安全的序列化算法，虽然效率略低，但可以屏蔽许多安全问题，开发者也可以自行实现协议解决效率和安全问题。</li></ul><p><a href="https://www.zhihu.com/question/640872750/answer/3376148295" target="_blank" rel="noreferrer">electron有preload导入node的module，为什么常见情况都是使用相对低效的ipc？ - 知乎</a></p><h2 id="asar-归档" tabindex="-1">asar 归档 <a class="header-anchor" href="#asar-归档" aria-label="Permalink to &quot;asar 归档&quot;">​</a></h2><ul><li>只读、随机访问（虚拟文件夹）</li><li>用 JSON 存储信息，易于实现解析器</li><li>规避文件路径太长（win）</li><li>减少文件数，加快安装</li></ul><p><a href="https://quickapp.vivo.com.cn/quickapp-ide-asar/" target="_blank" rel="noreferrer">快应用开发工具之 asar</a></p><h2 id="生产包热更新" tabindex="-1">生产包热更新 <a class="header-anchor" href="#生产包热更新" aria-label="Permalink to &quot;生产包热更新&quot;">​</a></h2><p>方案：asar（主进程） + update.zip(渲染进程)</p><p>需要拆项目</p><ul><li>降低迭代成本（分发带宽？）</li><li>提升</li></ul><h2 id="webview" tabindex="-1">webview <a class="header-anchor" href="#webview" aria-label="Permalink to &quot;webview&quot;">​</a></h2><p>默认没有网络缓存？</p><h3 id="webview-vs-browserview" tabindex="-1">webview vs browserview <a class="header-anchor" href="#webview-vs-browserview" aria-label="Permalink to &quot;webview vs browserview&quot;">​</a></h3><p>最大的区别在于 browserview 托管于 main process 而不是 renderer。这非常类似于 Chrome 中对页面的处理方式，因此可以获得很高的页面响应速度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><ul><li>系统差异，windows 无法 open？</li></ul><h3 id="白屏" tabindex="-1">白屏 <a class="header-anchor" href="#白屏" aria-label="Permalink to &quot;白屏&quot;">​</a></h3><p>windows 兼容性，如 windows server。解决：追加 --no-sandbox 或 打包 32 位版本</p><p>Win7+，不支持 arm</p><p>MacOS 10.10+</p><p><a href="https://stackoverflow.com/questions/36306450/what-is-minimum-system-requirements-to-run-electron-apps" target="_blank" rel="noreferrer">javascript - What is minimum system requirements to run electron apps? - Stack Overflow</a> 事件: &#39;render-process-gone’  判断 reason</p><p><a href="https://www.electronjs.org/zh/docs/latest/api/app#%E4%BA%8B%E4%BB%B6-render-process-gone" target="_blank" rel="noreferrer">https://www.electronjs.org/zh/docs/latest/api/app#%E4%BA%8B%E4%BB%B6-render-process-gone</a></p><p>增加消息提示，让用户重新打开</p><p><a href="./[https://juejin.cn/post/7136124646079856671](https://juejin.cn/post/7136124646079856671).html">【Electron】vue+electron白屏问题的解决方案 - 掘金</a></p><h3 id="webview-窗口打开慢" tabindex="-1">webview 窗口打开慢 <a class="header-anchor" href="#webview-窗口打开慢" aria-label="Permalink to &quot;webview 窗口打开慢&quot;">​</a></h3><ol><li>后台预热，隐藏窗口，定位到屏幕之外 + skipTaskBar任务栏不可见</li><li>窗口池，复用</li><li>常驻，通用类窗口，如通知、图片查看器</li></ol><p>分享这半年的 Electron 应用开发和优化经验 - 掘金 <a href="https://juejin.cn/post/6844904029231775758" target="_blank" rel="noreferrer">https://juejin.cn/post/6844904029231775758</a></p><h3 id="拖拽下载" tabindex="-1">拖拽下载 <a class="header-anchor" href="#拖拽下载" aria-label="Permalink to &quot;拖拽下载&quot;">​</a></h3><p>event.sender.startDrag <a href="https://www.electronjs.org/zh/docs/latest/api/web-contents#contentsstartdragitem" target="_blank" rel="noreferrer">https://www.electronjs.org/zh/docs/latest/api/web-contents#contentsstartdragitem</a><a href="https://www.electronjs.org/zh/docs/latest/tutorial/native-file-drag-drop" target="_blank" rel="noreferrer">https://www.electronjs.org/zh/docs/latest/tutorial/native-file-drag-drop</a></p><p>不能监听系统事件，只适合本地文件拖拽</p><p>原因：</p><ol><li>无法拿到目标路径</li><li>拖拽到系统本地，走了系统行为（下载文件 URL 到临时目录，再拷贝到目标文件夹）</li><li>文件夹没有 URL，无法下载 <a href="https://github.com/liupan1890/aliyunpan/issues/576" target="_blank" rel="noreferrer">https://github.com/liupan1890/aliyunpan/issues/576</a> 参考 vscode，只支持单文件，但这只是本地间 <a href="https://github.com/electron/electron/issues/7118#issuecomment-483681104" target="_blank" rel="noreferrer">https://github.com/electron/electron/issues/7118#issuecomment-483681104</a><a href="https://cloud.tencent.com/developer/article/1562722" target="_blank" rel="noreferrer">https://cloud.tencent.com/developer/article/1562722</a></li></ol><p><a href="https://github.com/ascoders/weekly/blob/master/%25E5%2589%258D%25E6%25B2%25BF%25E6%258A%2580%25E6%259C%25AF/59.%25E7%25B2%25BE%25E8%25AF%25BB%25E3%2580%258A%25E5%25A6%2582%25E4%25BD%2595%25E5%2588%25A9%25E7%2594%25A8%2520Nodejs%2520%25E7%259B%2591%25E5%2590%25AC%25E6%2596%2587%25E4%25BB%25B6%25E5%25A4%25B9%25E3%2580%258B.md" target="_blank" rel="noreferrer">weekly/59.精读《如何利用 Nodejs 监听文件夹》.md at master · ascoders/weekly</a></p><p><a href="https://juejin.cn/post/7095557874658574373#heading-1" target="_blank" rel="noreferrer">electron 拖拽未下载文件到本地功能实现 - 掘金</a><a href="https://pinkcle.com/electron/dragdrop.html" target="_blank" rel="noreferrer">Electron桌面端拖拽下载的实现 | 新时代农民工的日常</a></p><p>替代方案：监听系统文件夹变化，局限是适合有限监听的文件夹 主要风险：权限、兼容性</p><p>vscode 窗口内部拖拽实现，由于 startDrag 不支持内部，改用 e.dataTransfer.setData <a href="https://github.com/electron/electron/issues/7118#issuecomment-483681104" target="_blank" rel="noreferrer">https://github.com/electron/electron/issues/7118#issuecomment-483681104</a></p><p><a href="https://www.mo4tech.com/simple-drag-and-drop-function-in-electron.html" target="_blank" rel="noreferrer">Simple drag and drop function in Electron - Moment For Technology</a></p><h2 id="异常捕获" tabindex="-1">异常捕获 <a class="header-anchor" href="#异常捕获" aria-label="Permalink to &quot;异常捕获&quot;">​</a></h2><p>兜底捕获</p><ul><li>主进程不加，会异常退出 <code>process.on(&#39;uncaughtException&#39;</code></li><li>渲染进程，该进程会退出，不影响其他渲染进程或主进程 <code>window.onerror</code></li></ul><h3 id="渲染进程" tabindex="-1">渲染进程 <a class="header-anchor" href="#渲染进程" aria-label="Permalink to &quot;渲染进程&quot;">​</a></h3><p>表现：白屏、黑屏，窗口在但没有内容</p><ul><li>JavaScript 错误，未捕获的异常或死循环，可能会导致进程被终止</li><li>手动终止</li><li>内存耗尽</li></ul><p>事件：render-process-gone，处理参考 白屏部分</p><blockquote><p>Sentry 主要用于捕获 JavaScript 异常和错误以及 Electron 主进程中的问题，包括<code>process.on(&#39;uncaughtException&#39;</code></p></blockquote><p><a href="./electron-render-oom.html">electron-render-oom</a></p><h3 id="主进程" tabindex="-1">主进程 <a class="header-anchor" href="#主进程" aria-label="Permalink to &quot;主进程&quot;">​</a></h3><p>封装参考 <a href="https://github.dev/sindresorhus/electron-unhandled/blob/a302ae5367af900872d889cdb47fe26907fa47fe/index.js#L123" target="_blank" rel="noreferrer">https://github.dev/sindresorhus/electron-unhandled/blob/a302ae5367af900872d889cdb47fe26907fa47fe/index.js#L123</a></p><h3 id="crashreporter" tabindex="-1">crashReporter <a class="header-anchor" href="#crashreporter" aria-label="Permalink to &quot;crashReporter&quot;">​</a></h3><p>electron 的一个模块，收集主进程崩溃信息，支持设置上报地址，可配置 sentry 使用</p><p>crash free sessions 免于崩溃、即正常的会话数，用 100 减去即崩溃的会话数</p><p>存储用户目录：Crashpad</p><p><a href="https://www.electronjs.org/docs/latest/api/crash-reporter" target="_blank" rel="noreferrer">https://www.electronjs.org/docs/latest/api/crash-reporter</a></p><h2 id="打包" tabindex="-1">打包 <a class="header-anchor" href="#打包" aria-label="Permalink to &quot;打包&quot;">​</a></h2><p><a href="https://www.electronjs.org/docs/latest/tutorial/tutorial-packaging" target="_blank" rel="noreferrer">https://www.electronjs.org/docs/latest/tutorial/tutorial-packaging</a></p><p>测试 electron v21 空项目 dmg 220Mb</p><p><a href="https://sysin.org/blog/macos-if-crashes-when-opening/" target="_blank" rel="noreferrer">macOS 提示：“应用程序” 已损坏，无法打开的解决方法总结 - sysin | SYStem INside | 软件与技术分享</a></p><h2 id="electron-forge-cli" tabindex="-1">electron-forge cli <a class="header-anchor" href="#electron-forge-cli" aria-label="Permalink to &quot;electron-forge cli&quot;">​</a></h2><h2 id="webview-1" tabindex="-1">webview <a class="header-anchor" href="#webview-1" aria-label="Permalink to &quot;webview&quot;">​</a></h2><p>Preload scripts 类似 chrome 扩展的 content scripts</p><p>主进程是 nodejs 环境，有完全系统访问权</p><p>渲染进程运行页面，安全原因默认不能运行 nodejs</p><p>官方 contextBridge，显式声明暴露的能力</p><p>使用executeJavaScript方法可以在主进程中向webview注入方法，使用preload脚本可以在渲染进程中向webview注入方法。</p><p>进程间通信：<a href="https://www.electronjs.org/docs/latest/tutorial/tutorial-preload#communicating-between-processes" target="_blank" rel="noreferrer">Using Preload Scripts | Electron</a></p><p><a href="https://stackoverflow.com/questions/71791530/electron-preload-vs-electron-main" target="_blank" rel="noreferrer">node.js - Electron Preload vs Electron Main - Stack Overflow</a></p><p>第三方依赖 bug <a href="https://github.com/electron/forge/issues/2931#issuecomment-1306377240" target="_blank" rel="noreferrer">https://github.com/electron/forge/issues/2931#issuecomment-1306377240</a></p><p><a href="https://blog.csdn.net/a0405221/article/details/120928463" target="_blank" rel="noreferrer">解决electron嵌入webview显示空白无法使用_electron webview 不显示_谢泽的网络日志的博客-CSDN博客</a></p><p><a href="https://www.w3cways.com/2459.html" target="_blank" rel="noreferrer">electron中与webview的通讯-Web前端(W3Cways.com) - Web前端学习之路</a></p><p>为 webview 注入方法，原理： <a href="https://www.electronjs.org/docs/latest/tutorial/context-isolation#before-context-isolation-disabled" target="_blank" rel="noreferrer">Context Isolation | Electron</a></p><p>如果contextIsolation为false，那么web页面中的JS可以影响Electron内部渲染时的JS代码和预加载脚本执行。比如先入侵 web 加入恶意脚本，再传递到 preload node 环境。<strong>远程代码执行漏洞（RCE）</strong></p><p>contextIsolation 环境上下文隔离开关，是在 Electron 5.0 版本中引入的，默认值是 false。从 12.0 版本开始，默认值变为 true</p><p><a href="https://www.freebuf.com/articles/web/252806.html" target="_blank" rel="noreferrer">挖洞经验 | 综合三个Bug实现Discord桌面应用RCE漏洞 - FreeBuf网络安全行业门户</a></p><h2 id="contextbridge" tabindex="-1">contextBridge <a class="header-anchor" href="#contextbridge" aria-label="Permalink to &quot;contextBridge&quot;">​</a></h2><p>属于 render process，中间隔离环境，双向同步桥</p><h2 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to &quot;版本&quot;">​</a></h2><p>Electron 22, which contains Chromium 108, will thus be the last supported version.</p><p>In line with Chromium&#39;s deprecation policy, <em>Electron</em> will end support of <em>Windows 7</em>, Windows 8 and Windows 8.1 beginning in <em>Electron</em> 23.</p><p>不再收到更新支持，有可能能运行？</p><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h2><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://stackoverflow.com/questions/36072035/how-to-open-new-window-in-place-of-current-window-in-electron/38043021" target="_blank" rel="noreferrer">javascript - how to open new window in place of current window in Electron - Stack Overflow</a><a href="https://www.my-fe.pub/post/electron-note.html" target="_blank" rel="noreferrer">Electron简单笔记 - 小翼的前端天地</a><a href="https://www.codota.com/code/javascript/functions/electron/WebContents/on" target="_blank" rel="noreferrer">electron.WebContents.on JavaScript and Node.js code examples | Codota</a><a href="https://stackoverflow.com/questions/39091964/remove-menubar-from-electron-app" target="_blank" rel="noreferrer">node.js - Remove menubar from Electron app - Stack Overflow</a><a href="https://stackoverflow.com/questions/31171597/atom-electron-close-the-window-with-javascript" target="_blank" rel="noreferrer">Atom Electron - Close the window with javascript - Stack Overflow</a></p><p><a href="https://github.com/cawa-93/vite-electron-builder" target="_blank" rel="noreferrer">cawa-93/vite-electron-builder: Secure boilerplate for Electron app based on Vite. TypeScript + Vue/React/Angular/Svelte/Vanilla</a></p><p><a href="https://juejin.cn/post/6999257401522126856" target="_blank" rel="noreferrer">electron多进程方案解决界面卡顿 - 掘金</a></p><p><a href="https://blackglory.me/notes/electron" target="_blank" rel="noreferrer">https://blackglory.me/notes/electron</a></p><h2 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h2><p>测量然后优化，vscode 成功经验，官方给出了 checklist，可逐项检查</p><ol><li>延迟 require（IO、递归引用）和 new</li><li>V8 Snapshot，预处理 JS</li></ol><p><a href="https://blog.inkdrop.app/how-to-make-your-electron-app-launch-1000ms-faster-32ce1e0bb52c" target="_blank" rel="noreferrer">How to make your Electron app launch 1,000ms faster | by Takuya Matsuyama | Dev as Life</a><a href="https://zhuanlan.zhihu.com/p/700466961" target="_blank" rel="noreferrer">简单有效的 chromium 内存优化 - 知乎</a></p><h2 id="ffi" tabindex="-1">FFI <a class="header-anchor" href="#ffi" aria-label="Permalink to &quot;FFI&quot;">​</a></h2><h3 id="node-ffi-napi" tabindex="-1">node-ffi &amp; napi <a class="header-anchor" href="#node-ffi-napi" aria-label="Permalink to &quot;node-ffi &amp; napi&quot;">​</a></h3><blockquote><p>外部函数接口</p></blockquote><p>node-ffi 和 napi 都是 Node.js 中用于访问本地代码的工具，但它们有不同的设计目的和使用场景。</p><p>node-ffi 是一个 Node.js 模块，它允许你调用本地动态链接库中的函数，而无需编写 C++ 绑定代码。node-ffi 的主要设计目的是为了让 Node.js 开发者能够方便地访问本地系统功能，例如操作系统 API、硬件驱动程序等。使用 node-ffi，你可以在 Node.js 中轻松地调用 C 语言编写的动态链接库，而无需编写任何 C++ 绑定代码。</p><p>而 napi 是 Node.js 提供的一组 API，它允许开发者编写可跨平台、可移植的 C++ 扩展，并且这些扩展可以在不同版本的 Node.js 上运行。napi 的主要设计目的是为了让开发者能够编写高效、可靠的 Node.js 扩展，而不必考虑不同版本的 Node.js 之间的差异。使用 napi，你可以更轻松地编写跨平台的 Node.js 扩展，并且这些扩展可以在多个版本的 Node.js 上运行。</p><p>因此，node-ffi 和 napi 在设计目的和使用场景上存在差异。如果你需要快速访问本地系统功能，那么 node-ffi 是一个很好的选择；如果你需要编写可跨平台的高效 Node.js 扩展，那么 napi 是更好的选择。</p><p><a href="https://nodejs.org/api/n-api.html#node-api" target="_blank" rel="noreferrer">https://nodejs.org/api/n-api.html#node-api</a></p><h3 id="koffi" tabindex="-1">koffi <a class="header-anchor" href="#koffi" aria-label="Permalink to &quot;koffi&quot;">​</a></h3><p>在Koffi中，指针是一个变量，它保存了另一个变量或对象的内存地址。&quot;koffi.decode()&quot;函数允许你访问特定内存地址上存储的数据，并将其解释为JS函数。</p><p>如果您要在JS环境中使用&quot;koffi.decode()&quot;函数来获取JS函数，可能是为了与Koffi代码进行交互，或者将Koffi代码嵌入到现有的JS应用程序中。这样可以利用Koffi的特性和功能，并与现有的JS代码进行集成。</p><p><a href="https://koffi.dev/functions?highlight=decode" target="_blank" rel="noreferrer">https://koffi.dev/functions?highlight=decode</a></p><h3 id="ffi-直接调用已有的动态库-有性能损耗吗" tabindex="-1">FFI 直接调用已有的动态库，有性能损耗吗 <a class="header-anchor" href="#ffi-直接调用已有的动态库-有性能损耗吗" aria-label="Permalink to &quot;FFI 直接调用已有的动态库，有性能损耗吗&quot;">​</a></h3><p>使用FFI（Foreign Function Interface）直接调用已有的动态库通常会比使用原生模块性能略有损耗，因为FFI需要在运行时进行<strong>动态链接和调用，而原生模块则是静态链接，性能更高</strong>。这种性能损耗通常是很小的，特别是对于大部分应用来说，可以忽略不计。因此，如果开发成本和快速迭代对你的项目更为重要，FFI是一个很好的选择。</p><h2 id="原生渲染" tabindex="-1">原生渲染 <a class="header-anchor" href="#原生渲染" aria-label="Permalink to &quot;原生渲染&quot;">​</a></h2><p>场景：需要 webgl 渲染，如视频、图片像素 IPC 不适合传输大量数据 解决方案： 将窗体背景色调成透明，同时增加一个子窗口装载SDL，原生渲染 opengl 交互事件需要透传给原生模块</p><p>共享内存，没有有效方案</p><h2 id="napi-rust" tabindex="-1">NAPI &amp; Rust <a class="header-anchor" href="#napi-rust" aria-label="Permalink to &quot;NAPI &amp; Rust&quot;">​</a></h2><p><a href="https://johns.codes/blog/exposing-a-rust-library-to-node-with-napirs" target="_blank" rel="noreferrer">Exposing a Rust Library to Node with Napi-rs</a></p><h2 id="qt" tabindex="-1">QT <a class="header-anchor" href="#qt" aria-label="Permalink to &quot;QT&quot;">​</a></h2><p>Qt是一个跨平台的C++应用程序开发框架，它提供了丰富的功能和高性能。Qt应用程序通常被编译为本地机器码，因此在性能方面表现较好。Qt还有一个轻量级的版本Qt Quick，它使用QML语言来构建用户界面，可以实现更快的渲染和动画效果。</p><p>由于 Chromium 需要同时运行JavaScript和渲染网页，Electron应用程序的性能可能相对较低，尤其是在处理大量数据或运行复杂计算时。</p><h2 id="worker-多线程" tabindex="-1">Worker 多线程 <a class="header-anchor" href="#worker-多线程" aria-label="Permalink to &quot;Worker 多线程&quot;">​</a></h2><p>在 Electron 中，你可以直接使用 Node.js 的多线程模块 <code>worker_threads</code> 来实现多线程任务，而无需使用 Web Worker。</p><h2 id="缓存管理策略" tabindex="-1">缓存管理策略 <a class="header-anchor" href="#缓存管理策略" aria-label="Permalink to &quot;缓存管理策略&quot;">​</a></h2><p><strong>缓存淘汰策略</strong>：当缓存空间不足时，应用程序需要决定淘汰哪些数据以腾出空间存储新数据。如 LRU。</p><h2 id="高清屏幕" tabindex="-1">高清屏幕 <a class="header-anchor" href="#高清屏幕" aria-label="Permalink to &quot;高清屏幕&quot;">​</a></h2><p>clientX 表示光标位置</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>const offsetX = Math.round((clientX - canvasImgRect.value.left) * screenScaleFactor.value);</span></span></code></pre></div><h2 id="dev-tools" tabindex="-1">dev tools <a class="header-anchor" href="#dev-tools" aria-label="Permalink to &quot;dev tools&quot;">​</a></h2><p>load api</p><p>复用 chrome 安装的插件，封装的 npm 插件主要是解决路径和插件配置。 独立 npm app connect 没跑通</p><p><a href="https://www.electronjs.org/docs/latest/tutorial/devtools-extension#manually-loading-a-devtools-extension" target="_blank" rel="noreferrer">DevTools Extension | Electron</a></p><p>npm 包 electron-devtools-installer，使用了过时语法，并且从 chrome web store 下载，尽管官网依然有推荐。</p><p>如果使用 forge 或 builder ，也有对应方式</p><ul><li>[ ] <a href="https://xie.infoq.cn/article/9d3dd2687c865d8caad3d32fd" target="_blank" rel="noreferrer">解锁前端新潜能：如何使用 Rust 锈化前端工具链_taro_京东零售技术_InfoQ写作社区</a></li></ul><h2 id="跨进程-线程共享大量数据" tabindex="-1">跨进程/线程共享大量数据 <a class="header-anchor" href="#跨进程-线程共享大量数据" aria-label="Permalink to &quot;跨进程/线程共享大量数据&quot;">​</a></h2><p>SharedArrayBuffer 是通用方案，共享二进制数据缓冲区 比如在不同 Web Workers 之间，免去复制</p><p>需要设置 header 安全头</p>`,163),n=[l];function i(s,p,c,h,d,f){return a(),r("div",null,n)}const w=e(o,[["render",i]]);export{b as __pageData,w as default};
